import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

interface Project {
    title: string;
    description: string;
    image: string;
    technologies: string[];
    liveLink?: string;
    githubLink?: string;
}

@Component({
    selector: 'app-projects',
    standalone: true,
    imports: [CommonModule],
    template: `
    <section id="projects" class="projects-section">
      <div class="container">
        <h2 class="section-title">Featured Projects</h2>
        <div class="projects-grid">
          <div class="project-card fade-in" *ngFor="let project of projects">
            <div class="project-image">
              <div class="placeholder-img">{{ project.title[0] }}</div>
              <!-- In real app: <img [src]="project.image" [alt]="project.title"> -->
            </div>
            <div class="project-content">
              <h3>{{ project.title }}</h3>
              <p>{{ project.description }}</p>
              <div class="tech-stack">
                <span class="tech-chip" *ngFor="let tech of project.technologies">{{ tech }}</span>
              </div>
              <div class="project-links">
                <a *ngIf="project.liveLink" [href]="project.liveLink" target="_blank" class="btn btn-sm btn-primary">Live Demo</a>
                <a *ngIf="project.githubLink" [href]="project.githubLink" target="_blank" class="btn btn-sm btn-outline">GitHub</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  `,
    styles: [`
    .projects-section { background-color: var(--card-bg); }
    .section-title { text-align: center; margin-bottom: 4rem; font-size: 2.5rem; color: var(--primary-color); }
    
    .projects-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 2.5rem;
    }

    .project-card {
      background: var(--bg-color);
      border-radius: 1rem;
      overflow: hidden;
      box-shadow: 0 4px 20px rgba(0,0,0,0.05);
      transition: transfom 0.3s, box-shadow 0.3s;

      &:hover {
        transform: translateY(-8px);
        box-shadow: 0 12px 30px rgba(0,0,0,0.1);
      }
    }

    .project-image {
      height: 200px;
      background: linear-gradient(135deg, #e0e7ff, #f3e8ff);
      display: flex;
      align-items: center;
      justify-content: center;
      
      .placeholder-img {
        font-size: 4rem;
        font-weight: 700;
        color: rgba(37, 99, 235, 0.2);
      }
    }

    .project-content {
      padding: 1.5rem;

      h3 { margin-bottom: 0.5rem; font-size: 1.4rem; }
      
      p {
        color: var(--text-color);
        opacity: 0.8;
        font-size: 0.95rem;
        margin-bottom: 1rem;
        display: -webkit-box;
        -webkit-line-clamp: 3;
        -webkit-box-orient: vertical;
        overflow: hidden;
      }
    }

    .tech-stack {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-bottom: 1.5rem;
    }

    .tech-chip {
      background-color: var(--card-bg);
      color: var(--primary-color);
      padding: 0.25rem 0.75rem;
      border-radius: 50px;
      font-size: 0.8rem;
      font-weight: 500;
      border: 1px solid rgba(37, 99, 235, 0.1);
    }

    .project-links {
      display: flex;
      gap: 1rem;
    }

    .btn-sm {
      padding: 0.5rem 1rem;
      font-size: 0.9rem;
    }
  `]
})
export class ProjectsComponent {
    projects: Project[] = [
        {
            title: 'Commercial Monitoring Dashboard',
            description: 'A comprehensive dashboard for business analytics, tracking sales performance and KPIs in real-time.',
            image: 'assets/dashboard.jpg',
            technologies: ['Angular', 'Spring Boot', 'JWT', 'Chart.js'],
            liveLink: '#',
            githubLink: '#'
        },
        {
            title: 'Event & Ticket Reservation',
            description: 'Platform allows users to browse events, book tickets securely, and manage reservations via a user-friendly interface.',
            image: 'assets/events.jpg',
            technologies: ['Angular', 'Java', 'MySQL'],
            liveLink: '#',
            githubLink: '#'
        },
        {
            title: 'Travel Agency System',
            description: 'Management system for travel agencies to handle bookings, customers, and travel packages efficiently.',
            image: 'assets/travel.jpg',
            technologies: ['PHP', 'Laravel', 'Bootstrap', 'MySQL'],
            githubLink: '#'
        },
        {
            title: 'Secure Auth System',
            description: 'Robust authentication service providing secure login, registration, and role-based access control.',
            image: 'assets/auth.jpg',
            technologies: ['Spring Security', 'JWT', 'Angular'],
            githubLink: '#'
        }
    ];
}
